 "content": "def transform(grid):
    """Compress each 3x3 patch to its non-background marker color."""
    height = len(grid) // 3
    width = len(grid[0]) // 3
    output = [[0 for _ in range(width)] for _ in range(height)]
    for block_r in range(height):
        for block_c in range(width):
            colors = {
                grid[r][c]
                for r in range(block_r * 3, block_r * 3 + 3)
                for c in range(block_c * 3, block_c * 3 + 3)
                if grid[r][c] not in (0, 5)
            }
            if colors:
                output[block_r][block_c] = min(colors)
    return output
